import zipfile
import re
import xml.etree.ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
NS = {'m': M, 'r': R}
RID = '{%s}id' % R


def get_text(el):
    return ''.join(t.text or '' for t in el.iter('{%s}t' % M))


def parse_workbook(z):
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(sh.get('name'), sh.get(RID)) for sh in wb_root.find('m:sheets', NS)]
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {rel.get('Id'): rel.get('Target') for rel in rels_root}
    return sheets, rel_map


def cell_value(c, shared):
    t = c.get('t')
    v = c.find('m:v', NS)
    isel = c.find('m:is', NS)
    if t == 's' and v is not None:
        return shared[int(v.text)]
    if t == 'inlineStr' and isel is not None:
        return get_text(isel)
    if t == 'str' and v is not None:
        return v.text
    if t == 'b' and v is not None:
        return v.text
    if v is not None:
        return v.text
    return None


with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    sheets, rel_map = parse_workbook(z)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        shared = [get_text(si) for si in ss_root.findall('m:si', NS)]

    rows = {}
    for name, rid in sheets:
        tgt = rel_map[rid].lstrip('/')
        if not tgt.startswith('xl/'):
            tgt = 'xl/' + tgt
        root = ET.fromstring(z.read(tgt))
        sd = root.find('m:sheetData', NS)
        for row in sd:
            rnum = int(row.get('r'))
            cells = {c.get('r'): c for c in row}
            rows[rnum] = cells

# Expense rows: rows 11-22 per the sheet's SUM(C11:C22) total-expenses formula
expense_rows = range(11, 23)
per_category = {}
items = []
for r in expense_rows:
    cells = rows.get(r, {})
    a = cells.get('A%d' % r)
    b = cells.get('B%d' % r)
    c = cells.get('C%d' % r)
    if c is None or c.get('t') == 's':
        continue
    amt = float(cell_value(c, shared))
    cat = cell_value(a, shared) if a is not None else '(none)'
    item = cell_value(b, shared) if b is not None else '(none)'
    per_category[cat] = per_category.get(cat, 0.0) + amt
    items.append((r, cat, item, amt))

total = sum(amt for _, _, _, amt in items)
print("Expense line items:")
for r, cat, item, amt in items:
    print("  row %d | %-15s | %-15s | %.2f" % (r, cat, item, amt))
print("\nExpenses by category:")
for cat, amt in sorted(per_category.items()):
    print("  %-15s %.2f" % (cat, amt))
print("\nTOTAL EXPENSES (all categories): %.2f" % total)

# Cross-check against the file's own formula range
formula_sum = sum(float(rows[r]['C%d' % r].find('m:v', NS).text) for r in range(11, 23))
print("Cross-check SUM(C11:C22) from file values: %.2f (match: %s)"
      % (formula_sum, abs(formula_sum - total) < 1e-9))

